/// A tiny stand-in for the PostgREST/Realtime surface the chat screen
/// touches. It serves the fixture avatars over HTTP so the app renders real
/// `Image.network` pixels without reaching the public internet.
class FixtureServer {
  FixtureServer._(this._server, this._directory);

  final HttpServer _server;
  final Directory _directory;

  static Future<FixtureServer> start({int port = 0}) async {
    final server = await HttpServer.bind(InternetAddress.loopbackIPv4, port);
    final directory = Directory(
      '${Directory.current.path}${Platform.pathSeparator}tool'
      '${Platform.pathSeparator}readme_capture${Platform.pathSeparator}fixtures',
    );
    final fixture = FixtureServer._(server, directory);
    unawaited(fixture._serve());
    return fixture;
  }

  String get baseUrl => 'http://127.0.0.1:${_server.port}';

  Future<void> _serve() async {
    await for (final request in _server) {
      try {
        if (WebSocketTransformer.isUpgradeRequest(request)) {
          final socket = await WebSocketTransformer.upgrade(request);
          unawaited(_serveRealtime(socket));
          continue;
        }
        final path = request.uri.path;
        // The client must not keep the connection alive: a persistent
        // connection leaves an idle timer behind in the test's fake clock.
        request.response.headers.set(HttpHeaders.connectionHeader, 'close');
        if (path.endsWith('.png')) {
          final name = path.substring(path.lastIndexOf('/') + 1);
          final file = File('${_directory.path}${Platform.pathSeparator}$name');
          if (file.existsSync()) {
            request.response
              ..statusCode = HttpStatus.ok
              ..headers.contentType = ContentType('image', 'png')
              ..add(file.readAsBytesSync());
            await request.response.close();
            continue;
          }
          // A missing fixture must be obvious rather than silent.
          request.response.statusCode = HttpStatus.notFound;
          await request.response.close();
          continue;
        }
        if (path.startsWith('/rest/v1/conversations')) {
          request.response
            ..statusCode = HttpStatus.ok
            ..headers.contentType = ContentType.json
            ..write(
              jsonEncode([
                {
                  'id': 'conv_0',
                  'match_id': 'match_0',
                  'created_at': '2026-11-01',
                },
              ]),
            );
          await request.response.close();
          continue;
        }
        if (path.startsWith('/rest/v1/messages')) {
          request.response
            ..statusCode = HttpStatus.ok
            ..headers.contentType = ContentType.json
            ..write(jsonEncode(demoMessages));
          await request.response.close();
          continue;
        }
        // Everything else (RPCs, auth, storage) answers with an empty
        // payload so no screen ever receives fabricated content.
        request.response
          ..statusCode = HttpStatus.ok
          ..headers.contentType = ContentType.json
          ..write(jsonEncode(path.contains('/rpc/') ? null : []));
        await request.response.close();
      } catch (_) {
        // A failed fixture request must never fail the capture.
      }
    }
  }

  /// A minimal stand-in for the Supabase Realtime endpoint.
  ///
  /// Realtime protocol `2.0.0` frames are positional JSON arrays:
  /// `[join_ref, ref, topic, event, payload]`.
  ///
  /// The chat transcript itself arrives over PostgREST, so the socket only
  /// has to accept the join and answer it. Answering the join keeps the
  /// client from retrying and keeps the capture free of stream errors.
  Future<void> _serveRealtime(WebSocket socket) async {
    await for (final frame in socket) {
      try {
        final parts = jsonDecode(frame as String) as List<dynamic>;
        if (parts.length < 5) continue;
        final joinRef = parts[0];
        final ref = parts[1];
        final topic = parts[2] as String;
        final event = parts[3] as String;
        if (event != 'phx_join' &&
            event != 'phx_leave' &&
            event != 'heartbeat') {
          continue;
        }
        socket.add(
          jsonEncode([
            joinRef,
            ref,
            topic,
            'phx_reply',
            {'status': 'ok', 'response': <String, Object>{}},
          ]),
        );
      } catch (_) {
        // Ignore anything that is not a Phoenix frame.
      }
    }
  }

  Future<void> close() => _server.close(force: true);
}

/// Downloads the fixture images before the screen is built.
///
/// The widget test runs on a fake clock, so an image request that starts
/// during a build never completes. Warming the image cache from the real
/// async zone means the screen finds every image already resolved and paints
/// it on the first frame.
Future<void> precacheFixtures(BuildContext context, List<String> urls) async {
  final configuration = createLocalImageConfiguration(context);
  for (final url in urls) {
    await _precache(NetworkImage(url), configuration);
    await _precache(CachedNetworkImageProvider(url), configuration);
  }
}

Future<void> _precache(
  ImageProvider provider,
  ImageConfiguration configuration,
) async {
  try {
    final completer = Completer<void>();
    provider
        .resolve(configuration)
        .addListener(
          ImageStreamListener(
            (ImageInfo image, bool synchronous) {
              if (!completer.isCompleted) completer.complete();
            },
            onError: (Object error, StackTrace? stackTrace) {
              // ignore: avoid_print
              print('[precache] ${provider.runtimeType} failed: $error');
              if (!completer.isCompleted) completer.complete();
            },
          ),
        );
    await completer.future;
  } catch (error) {
    // ignore: avoid_print
    print('[precache] ${provider.runtimeType} threw: $error');
  }
}

/// Loads the real Roboto and Material Icons fonts into the test engine.
///
/// The Flutter test runner renders every glyph as a filled box, which would
/// make the captures useless. The fonts ship with the Flutter SDK, so the
/// harness borrows them instead of carrying its own copies.
Future<void> loadRealFonts() async {
  final directory = _materialFontsDirectory();
  if (directory == null) return;

  final roboto = FontLoader('Roboto');
  for (final file in const [
    'roboto-light.ttf',
    'roboto-regular.ttf',
    'roboto-medium.ttf',
    'roboto-bold.ttf',
    'roboto-black.ttf',
    'roboto-italic.ttf',
  ]) {
    final bytes = _readFont(directory, file);
    if (bytes != null) roboto.addFont(Future<ByteData>.value(bytes));
  }
  await roboto.load();

  final icons = FontLoader('MaterialIcons');
  final iconBytes = _readFont(directory, 'materialicons-regular.otf');
  if (iconBytes != null) icons.addFont(Future<ByteData>.value(iconBytes));
  await icons.load();
}

ByteData? _readFont(Directory directory, String name) {
  final file = File('${directory.path}${Platform.pathSeparator}$name');
  if (!file.existsSync()) return null;
  return ByteData.sublistView(file.readAsBytesSync());
}

/// Walks up from the running Dart executable to the Flutter SDK root.
Directory? _materialFontsDirectory() {
  var directory = File(Platform.resolvedExecutable).parent;
  while (directory.parent.path != directory.path) {
    final candidate = Directory(
      '${directory.path}${Platform.pathSeparator}bin${Platform.pathSeparator}'
      'cache${Platform.pathSeparator}artifacts${Platform.pathSeparator}'
      'material_fonts',
    );
    if (candidate.existsSync()) return candidate;
    directory = directory.parent;
  }
  return null;
}
